<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>快送外卖 - 订单摘要</title>
    <style>
        body{font-family:Arial,sans-serif;margin:0;background:#f0f0f0;color:#333;}
        header{background:#ff5722;color:#fff;padding:15px 30px;display:flex;align-items:center;justify-content:space-between;}
        header h1{margin:0;font-size:20px;}
        nav a{color:#fff;margin:0 10px;text-decoration:none;}
        .container{max-width:900px;margin:auto;padding:20px;}
        .order-item{background:#fff;padding:15px;margin-bottom:10px;border-radius:6px;display:flex;justify-content:space-between;align-items:center;}
        .order-item div{flex:1;}
        .order-item .name{font-weight:bold;}
        .order-item .price{color:#ff5722;}
        .total{background:#fff;padding:15px;border-radius:6px;font-size:18px;text-align:right;margin-top:20px;}
        .checkout{background:#4caf50;color:#fff;border:none;padding:12px 24px;border-radius:6px;font-size:16px;cursor:pointer;margin-top:20px;display:block;width:100%;}
        footer{background:#333;color:#ccc;padding:15px;text-align:center;font-size:14px;}
    </style>
    <script>
        function loadCart(){
            const cart = JSON.parse(localStorage.getItem('cart')||'[]');
            const listDiv = document.getElementById('order-list');
            let total = 0;
            if(cart.length===0){
                listDiv.innerHTML='<p>购物车为空，请先添加菜品。</p>';
                document.getElementById('checkout-btn').style.display='none';
                return;
            }
            cart.forEach(item=>{
                const div = document.createElement('div');
                div.className='order-item';
                const subtotal = item.price * item.qty;
                total+=subtotal;
                div.innerHTML = `
                    <div class="name">${item.name}</div>
                    <div>数量: ${item.qty}</div>
                    <div class="price">¥${subtotal.toFixed(2)}</div>
                `;
                listDiv.appendChild(div);
            });
            document.getElementById('total-amount').textContent='¥'+total.toFixed(2);
        }
        function confirmOrder(){
            alert('订单已提交！感谢使用快送外卖。');
            localStorage.removeItem('cart');
            location.reload();
        }
        window.addEventListener('load',loadCart);
    </script>
</head>
<body>
<header>
    <h1>快送外卖</h1>
    <nav>
        <a href="index.html">首页</a>
        <a href="list.html">餐厅列表</a>
        <a href="order.html">我的订单</a>
    </nav>
</header>
<div class="container">
    <h2>订单摘要</h2>
    <div id="order-list"></div>
    <div class="total">合计：<span id="total-amount">¥0.00</span></div>
    <button id="checkout-btn" class="checkout" onclick="confirmOrder()">确认下单</button>
</div>
<footer>
    © 2026 快送外卖 | 成都市 | 联系电话：400-123-4567
</footer>
</html>
